package com.enterprise.core;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.ComponentScan;
import org.springframework.boot.autoconfigure.EnableAutoConfiguration;

// Explicitly breaking down the composite annotation for educational clarity
@Configuration
@EnableAutoConfiguration
@ComponentScan(basePackages = "com.enterprise.core")
public class ExplicitBootstrapApplication {

    @Bean
    public String customApplicationMessage() {
        return "Bootstrapped via decomposed meta-annotations!";
    }

    public static void main(String[] args) {
        SpringApplication.run(ExplicitBootstrapApplication.class, args);
    }
}
